    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        if addr not in self.regs:
            raise ValueError(f"Invalid register address: {addr}")

        # Read the current register value
        current_value = self.read_register(addr)

        if nbytes == 1:
            # For 1-byte access, update only the relevant bits
            current_value &= ~(0xFF << (8 - addr.bit_length()))
            current_value |= (data & 0xFF) << (8 - addr.bit_length())
        else:
            # For 2-byte access, update all bits
            current_value = data

        # Update the register with the new value
